WITH enriched AS (SELECT *, AVG(shipping_fee) OVER w_hist AS status_avg_shipping_fee, NTILE(4) OVER (PARTITION BY customer_id ORDER BY amount, id) AS amount_bucket, AVG(amount) OVER (PARTITION BY status) AS status_avg_amount FROM orders WINDOW w_hist AS (PARTITION BY status, channel)) SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee FROM enriched ORDER BY order_date DESC, amount;
